var J = 0.05, thEq = 0.2;
var K = params.f1K, B = params.f1B, tExt = params.f1Text;
var th = 0, w = 0, ang = [], eq = [];
for (var i = 0; i < helpers.n; i++) {
  var tau = -K * (th - thEq) - B * w + tExt;
  w = w + (tau / J) * helpers.dt;
  th = th + w * helpers.dt;
  th = helpers.clamp(th, -3, 3);
  ang.push(th * 180 / Math.PI);
  eq.push(thEq * 180 / Math.PI);
}
return { series: [ { label: 'joint angle θ', data: ang }, { label: 'equilibrium angle θ_eq', data: eq } ] };

var n = helpers.n, K = params.f2K, dth = params.f2Dth * Math.PI / 180;
var ang = [], t1 = [], t2 = [];
for (var i = 0; i < n; i++) {
  var p = i / (n - 1);
  var a = 10 * Math.sin(Math.PI * Math.min(p / 0.62, 1))
        - 18 * Math.exp(-Math.pow((p - 0.66) / 0.05, 2))
        + 6 * Math.exp(-Math.pow((p - 0.85) / 0.10, 2));
  var tq = -1.55 * Math.exp(-Math.pow((p - 0.50) / 0.11, 2))
         + 0.12 * Math.exp(-Math.pow((p - 0.08) / 0.05, 2));
  ang.push(a);
  t1.push(tq);
  t2.push(tq - K * dth);
}
return { x: ang, series: [ { label: 'nominal torque–angle loop', data: t1 }, { label: 'same instant, displaced by Δθ', data: t2 } ] };

demo.insightJs:
var x = result.x, y = result.series[0].data;
var i1 = Math.round(0.20 * (x.length - 1)), i2 = Math.round(0.45 * (x.length - 1));
var dx = (x[i2] - x[i1]) * Math.PI / 180;
var qs = Math.abs(dx) < 1e-6 ? 0 : (y[i2] - y[i1]) / dx;
var gap = params.f2K * params.f2Dth * Math.PI / 180;
return 'Through mid-stance the loop’s own slope — the quasi-stiffness — is about ' + qs.toFixed(1) + ' Nm/rad/kg, while a ' + params.f2Dth.toFixed(1) + '° displacement shifts the curve by ' + gap.toFixed(2) + ' Nm/kg. Two different numbers, and only the second one is the controller’s stiffness K.';

demo.computeJs:
var n = helpers.n, J = 0.06;
var out = [], xs = [];
for (var run = 0; run < 2; run++) {
  var th = 0, w = 0, d = [];
  for (var i = 0; i < n; i++) {
    var p = i / (n - 1);
    if (run === 0) xs.push(100 * p);
    var Kb = 60 + params.f3Peak * Math.exp(-Math.pow((p - 0.42) / 0.14, 2));
    var K = (run === 0) ? Kb : params.f3Kconst;
    var B = 0.03 * K + 0.5;
    var dist = params.f3Pert * Math.exp(-Math.pow((p - 0.15) / 0.05, 2));
    var acc = (-K * th - B * w + dist) / J;
    w = w + acc * helpers.dt;
    th = th + w * helpers.dt;
    th = helpers.clamp(th, -2, 2);
    d.push(th * 180 / Math.PI);
  }
  out.push(d);
}
return { x: xs, series: [ { label: 'biological K(φ) — like controller α', data: out[0] }, { label: 'constant K — like controller β', data: out[1] } ] };

