var kEarly = 60 + params.f3Peak * Math.exp(-Math.pow((0.15 - 0.42) / 0.14, 2));
return 'Early stance is where the biological trajectory is softest — about ' + kEarly.toFixed(0) + ' Nm/rad against the constant ' + params.f3Kconst.toFixed(0) + ' Nm/rad — so the same ' + params.f3Pert.toFixed(0) + ' Nm disturbance moves it ' + Math.abs(ma).toFixed(1) + '° versus ' + Math.abs(mb).toFixed(1) + '°. This is the paper’s Fig. 7 in miniature.';

demo.computeJs:
var n = helpers.n, Tc = 1.1;
var phase = 0, clock = 0, xs = [], pv = [], ck = [];
for (var i = 0; i < n; i++) {
  var t = i * helpers.dt;
  var rate = (t >= params.f4When && t < params.f4When + params.f4Dur) ? params.f4Slow : 1;
  phase = phase + rate * helpers.dt / Tc;
  clock = clock + helpers.dt / Tc;
  xs.push(t);
  pv.push(phase);
  ck.push(clock);
}
return { x: xs, series: [ { label: 'phase from thigh orientation', data: pv }, { label: 'fixed-rate clock', data: ck } ] };

